function useGameData(tripId: string) {
  const [poll,setPoll] = useState<Poll|null>(null), [votes,setVotes] = useState<Vote[]>([]), [nights,setNights] = useState<Night[]>([]), [games,setGames] = useState<Game[]>([]), [cards,setCards] = useState<Card[]>([]), [state,setState] = useState<State|null>(null), [error,setError] = useState("");
  const refresh = async () => {
    const [p,v,n,g,c,s] = await Promise.all([
      supabase.from("game_night_polls").select("*").eq("trip_id",tripId).maybeSingle(),
      supabase.from("game_night_votes").select("*").eq("trip_id",tripId),
      supabase.from("game_nights").select("*").eq("trip_id",tripId).order("week_number"),
      supabase.from("game_catalog").select("*").order("number"),
      supabase.rpc("game_card_view",{p_trip:tripId}),
      supabase.from("trip_play_state").select("*").eq("trip_id",tripId).maybeSingle()
    ]);
    const failure = [p,v,n,g,c,s].find((r) => r.error)?.error;
    if (failure) { setError(friendlyError(failure)); return; }
    setPoll(p.data); setVotes(v.data ?? []); setNights(n.data ?? []); setGames(g.data ?? []); setCards((c.data ?? []) as Card[]); setState(s.data); setError("");
  };
  useEffect(() => {
    void refresh();
    const channel = supabase.channel(`game-night-${tripId}-${Math.random()}`).on("postgres_changes",{ event:"*",schema:"public",table:"game_night_polls",filter:`trip_id=eq.${tripId}` },()=>void refresh()).on("postgres_changes",{event:"*",schema:"public",table:"game_night_votes",filter:`trip_id=eq.${tripId}`},()=>void refresh()).on("postgres_changes",{event:"*",schema:"public",table:"game_nights",filter:`trip_id=eq.${tripId}`},()=>void refresh()).on("postgres_changes",{event:"*",schema:"public",table:"trip_play_state",filter:`trip_id=eq.${tripId}`},()=>void refresh()).subscribe();
    const timer = window.setInterval(() => { if (!document.hidden) void refresh(); }, 12000);
    return () => { window.clearInterval(timer); void supabase.removeChannel(channel); };
  },[tripId]);
  return {poll,votes,nights,games,cards,state,error,refresh,setError};
}

function fmt(value: string, zone: string) { return fmtWhen(value, zone); }
function optionsOf(poll: Poll|null): string[] { return Array.isArray(poll?.options) ? poll.options.filter((x): x is string => typeof x === "string") : []; }
